-- 1. PERMISSIVE RLS POLICIES FOR ANONYMOUS & AUTHENTICATED BROWSING
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public can read categories" ON public.categories;
CREATE POLICY "Public can read categories" ON public.categories FOR SELECT TO anon, authenticated USING (true);

ALTER TABLE public.courses ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public can read published courses" ON public.courses;
CREATE POLICY "Public can read published courses" ON public.courses FOR SELECT TO anon, authenticated USING (is_published = true);

ALTER TABLE public.modules ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public can read modules" ON public.modules;
CREATE POLICY "Public can read modules" ON public.modules FOR SELECT TO anon, authenticated USING (true);

ALTER TABLE public.lessons ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public can read lessons" ON public.lessons;
CREATE POLICY "Public can read lessons" ON public.lessons FOR SELECT TO anon, authenticated USING (true);

ALTER TABLE public.system_settings ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public can read system_settings" ON public.system_settings;
CREATE POLICY "Public can read system_settings" ON public.system_settings FOR SELECT TO anon, authenticated USING (true);

ALTER TABLE public.website_content ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public can read website_content" ON public.website_content;
CREATE POLICY "Public can read website_content" ON public.website_content FOR SELECT TO anon, authenticated USING (true);

ALTER TABLE public.support_messages ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Anon can insert support_messages" ON public.support_messages;
CREATE POLICY "Anon can insert support_messages" ON public.support_messages FOR INSERT TO anon, authenticated WITH CHECK (true);

