INSERT INTO public.courses (id, title, slug, category_id, instructor_id, thumbnail_url, summary, description, price_ghs, is_free, duration, difficulty, is_published, is_featured, drive_folder_id, drive_folder_name, learning_objectives, requirements, completion_requirement)
VALUES ("crs-1", "AI Website Development Mastery", "ai-website-development-mastery", "cat-1", "usr-inst-1", "/src/assets/images/course_ai_webdev_1794843660816.jpg", "Watch Lesson 1 free on sign-in, then unlock the complete Google Drive AI Web Design Course (Detailed Tutorials, Hosting, Custom Domains & Bonuses) for GH₵ 50.", "Master AI-powered website design and publishing with Emmanuel Sansah. Fresh students watch Lesson 1 (1 MUST WATCH) free immediately after login. Complete the GH₵ 50 MTN Mobile Money payment to unlock the remaining Google Drive video modules—Detailed Tutorials, Other Website Examples, Hosting Your Website, Domain Name setup, Android App conversion, Troubleshooting, and Bonuses—using your sign-up email.", 50, false, "6 Weeks", "Beginner", true, true, "1Kzr26pgYSYro2pnP8W1lUFspy7_SwPQN", "AI Website Development Tutorials (Google Drive)", "[\"Follow the step-by-step AI Web Design curriculum from Lesson 1 free orientation\",\"Build real client and business websites with detailed AI tutorials and examples\",\"Host your finished website online and connect a custom domain name\",\"Package responsive web builds into Android apps and troubleshoot errors\"]"::jsonb, "[\"A laptop, desktop, or smartphone with internet access\",\"Valid sign-up Gmail address to receive full Google Drive video access after payment\"]"::jsonb, "Watch Lesson 1 free, complete GH₵ 50 MTN MoMo payment to unlock all remaining videos, and finish the course quiz.")
