VALUES ("crs-2", "AI Video Creation & Commercial Editing", "ai-video-creation-commercial-editing", "cat-2", "usr-inst-1", "/src/assets/images/course_ai_video_1794843660832.jpg", "Start with the free introduction video, then unlock the full AI Video Creation & Commercial Editing training series for GH₵ 50.", "Learn how creators and agencies produce studio-grade adverts, social reels, and explainers using generative AI video pipelines. Start with Lesson 1 free on fresh login, then unlock all remaining tutorials and Google Drive video folders using your sign-up email after GH₵ 50 Mobile Money confirmation.", 50, false, "5 Weeks", "Beginner", true, true, "1OccyWRAGt64BkaO3PXsLAXhInnfZG5uZ", "AI Video Creation Tutorials (Google Drive)", "[\"Write high-retention video scripts and shot lists with AI tools\",\"Generate consistent visual scenes, voiceovers, and studio B-roll\",\"Edit rhythmic timelines, captions, and commercial sound mixes\",\"Export commercial deliverables for YouTube, TikTok, Instagram, and clients\"]"::jsonb, "[\"Computer or smartphone capable of running modern video editors\",\"Valid sign-up email address for post-payment video folder access\"]"::jsonb, "Unlock all modules via GH₵ 50 MoMo verification and submit your 45-second commercial project.")
