VALUES ("crs-3", "Artificial Intelligence for Business & Education", "artificial-intelligence-business-education", "cat-3", "usr-inst-1", "/src/assets/images/course_ai_systems_1794843661238.jpg", "Practical AI implementation for educators, entrepreneurs, and teams looking to automate daily workflows.", "Go beyond casual chat usage. Understand how large language models work, build reliable document workflows, automate customer support drafts, create lesson plans, and maintain data privacy across your organization.", 150, false, "8 Weeks", "Intermediate", true, true, "[\"Design repeatable AI workflows for reporting, research, and curriculum design\",\"Evaluate AI outputs for factual accuracy and institutional compliance\",\"Integrate no-code automation bridges between forms, sheets, and email\"]"::jsonb, "[\"Familiarity with office productivity tools (Docs, Sheets, Email)\"]"::jsonb, "Complete all modules and pass the AI Systems Assessment.")
