VALUES ("crs-4", "Applied Prompt Engineering Studio", "applied-prompt-engineering-studio", "cat-4", "usr-inst-1", "/src/assets/images/course_ai_systems_1794843661238.jpg", "Master precision prompting patterns—chain-of-thought, structured JSON schemas, and reusable prompt libraries.", "Learn the engineering discipline behind reliable AI outputs. Stop guessing with vague one-liners and start writing deterministic system prompts, evaluation rubrics, and domain-specific templates.", 100, false, "4 Weeks", "Beginner", true, true, "[\"Apply role, context, constraint, and output-format frameworks\",\"Use few-shot examples to enforce consistent tone and structure\",\"Build a personal prompt library for coding, writing, and analysis\"]"::jsonb, "[\"Basic web browsing skills\"]"::jsonb, "Complete all modules and score 75%+ on the Prompt Engineering Exam.")
