VALUES ("crs-5", "Graphic Design Prompts & Modern Brand Identity", "graphic-design-modern-brand-identity", "cat-5", "usr-inst-1", "/src/assets/images/course_design_digital_1794843661469.jpg", "Start with Lesson 1 free, then unlock the complete Google Drive Graphic Design Prompts & Modern Brand Identity library after payment.", "A hands-on design academy track covering AI graphic design prompts, visual hierarchy, typography pairing, color theory, print-ready flyers, social media kits, and complete brand books. After payment confirmation, receive full Google Drive access to all Graphic Design Prompts & tutorials on your sign-up email.", 120, false, "6 Weeks", "Beginner", true, true, "1-X_O9cbsQJdXCwq-E2xHDh22SGGYx9ro", "Graphic Design Prompts & Tutorials (Google Drive)", "[\"Construct balanced typographic hierarchies and grid layouts\",\"Design vector logo marks and cohesive brand color systems\",\"Package print and digital brand assets for paying clients\"]"::jsonb, "[\"Laptop or desktop computer\"]"::jsonb, "Submit a complete 5-page Brand Identity Guide.")
