VALUES ("crs-6", "Full-Stack Web Development & TypeScript", "full-stack-web-development-typescript", "cat-6", "usr-inst-1", "/src/assets/images/course_ai_webdev_1794843660816.jpg", "Deep dive into modern JavaScript, TypeScript, React, Node.js REST APIs, and PostgreSQL/Supabase databases.", "Become a job-ready full-stack engineer. Build real authentication systems, relational schemas, REST endpoints, and responsive React applications with strict type safety.", 200, false, "10 Weeks", "Intermediate", true, false, "[\"Build type-safe React applications with hooks and state management\",\"Design REST APIs with Express and PostgreSQL/Supabase\",\"Implement secure password hashing, RBAC permissions, and deployment\"]"::jsonb, "[\"Basic familiarity with HTML/CSS or completion of AI Website Development\"]"::jsonb, "Complete all lessons and deploy a full-stack capstone.")
