VALUES ("crs-7", "Digital Skills & Computer Training Essentials", "digital-skills-computer-training", "cat-7", "usr-inst-1", "/src/assets/images/course_design_digital_1794843661469.jpg", "Introductory computer training covering cloud workspace tools, spreadsheets, documents, and online safety.", "Designed for students, job seekers, and professionals building strong everyday computer fluency. Learn file organization, business spreadsheets, slide decks, email etiquette, and cybersecurity essentials.", 50, false, "3 Weeks", "Beginner", true, false, "[\"Organize cloud drives, documents, and collaborative spreadsheets\",\"Protect personal and workplace accounts against phishing and scams\",\"Prepare professional reports and presentations efficiently\"]"::jsonb, "[\"Access to a computer or tablet\"]"::jsonb, "Complete all lessons and the Digital Literacy Quiz.")
