INSERT INTO public.website_content (id, hero_headline, hero_subheadline, about_title, about_mission, about_vision, announcement_banner, testimonials, faqs)
VALUES (1, "Master the Future with Artificial Intelligence.", "EK TECH SOLUTIONS equips ambitious learners across Ghana and beyond with practical training in AI Website Development (GH₵ 50), AI Video Creation (GH₵ 50), Prompt Engineering, and Modern Software Skills.", "Practical Technology Education Built for Real Outcomes", "To make world-class artificial intelligence, website development, and AI video creation skills accessible through structured online tutorials, hands-on projects, and direct mentorship from Emmanuel Sansah.", "Raising a generation of African and global builders who do not just consume technology, but design, automate, and ship meaningful digital products.", "Watch Lesson 1 Free on Sign-In — AI Website Learning & AI Video Creation are now GH₵ 50 each via MTN MoMo (0551464715).", "[{\"id\":\"tes-1\",\"name\":\"Kofi Agyemang\",\"role\":\"Freelance Web Designer\",\"organization\":\"Tema Digital Studio\",\"courseCompleted\":\"AI Website Development Mastery\",\"quote\":\"Watching the free Lesson 1 convinced me immediately. After my GH₵ 50 MoMo payment was confirmed on my sign-up email, I followed the detailed Google Drive tutorials and delivered two paid client websites.\"},{\"id\":\"tes-2\",\"name\":\"Ama Serwaa\",\"role\":\"Marketing Coordinator\",\"organization\":\"Accra Retail Collective\",\"courseCompleted\":\"Applied Prompt Engineering Studio\",\"quote\":\"Emmanuel Sansah explains everything clearly step by step. The prompt engineering templates cut our campaign copywriting and reporting time in half.\"},{\"id\":\"tes-3\",\"name\":\"Daniel Owusu\",\"role\":\"Content Producer\",\"organization\":\"Kumasi Media House\",\"courseCompleted\":\"AI Video Creation & Commercial Editing\",\"quote\":\"For just GH₵ 50, the AI Video Creation course transformed how we produce commercial adverts for local businesses.\"}]"::jsonb, "[{\"id\":\"faq-1\",\"category\":\"Enrolment & Payments\",\"question\":\"How do I unlock the rest of the videos after watching the free Lesson 1?\",\"answer\":\"Every newly registered or signed-in student can watch Lesson 1 (1 MUST WATCH) completely free. To unlock the remaining course videos and receive Google Drive access on your sign-up email, send GH₵ 50 (for AI Website Development or AI Video Creation) to MTN Mobile Money 0551464715 (EK TECH SOLUTIONS) and submit your Transaction ID inside your dashboard.\"},{\"id\":\"faq-2\",\"category\":\"Learning Format\",\"question\":\"Why do I need to use my sign-up email for payment verification?\",\"answer\":\"Once our administrator verifies your Mobile Money transfer, access to the remaining premium course videos in Instructor Emmanuel Sansah’s Google Drive library (emmanuelsansah020@gmail.com) is granted directly to your registered sign-up email address.\"},{\"id\":\"faq-3\",\"category\":\"Verification & Access\",\"question\":\"How long does Mobile Money payment verification take?\",\"answer\":\"Payments are manually verified by our administration team to protect students and prevent duplicate transaction IDs. Verification typically completes within 15 minutes to 2 hours, and you can also message 0551464715 on WhatsApp for urgent assistance.\"},{\"id\":\"faq-4\",\"category\":\"Certificates\",\"question\":\"Do I receive a certificate after completing a course?\",\"answer\":\"Yes. Upon completing all required lessons and passing the course quiz or practical assessment, an official EK TECH SOLUTIONS certificate signed by Emmanuel Sansah is issued in your Student Dashboard.\"},{\"id\":\"faq-5\",\"category\":\"Prerequisites\",\"question\":\"Do I need coding experience before joining AI Website Development?\",\"answer\":\"No prior programming background is required. Emmanuel Sansah walks you step by step from the free intro video through building, hosting, custom domains, and troubleshooting.\"}]"::jsonb)
ON CONFLICT (id) DO UPDATE SET hero_headline=excluded.hero_headline, hero_subheadline=excluded.hero_subheadline, testimonials=excluded.testimonials, faqs=excluded.faqs;
